export function maxProduct(values          )         {
let hi=values[0],lo=values[0],best=values[0];for(const x of values.slice(1)){const a=hi*x,b=lo*x;hi=Math.max(x,a,b);lo=Math.min(x,a,b);best=Math.max(best,hi);}return best;
}

